import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.DDY-poMm.js";const g=JSON.parse('{"title":"App 版本发布","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/app-release.md","filePath":"zh/guide/app-release.md","lastUpdated":1790683574000}'),p={name:"zh/guide/app-release.md"};function r(o,t,d,l,i,c){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="app-版本发布" tabindex="-1">App 版本发布 <a class="header-anchor" href="#app-版本发布" aria-label="Permalink to &quot;App 版本发布&quot;">​</a></h1><p>已经安装了 App 的用户，怎么知道有新版本？</p><p>从 v1.0.2 起，App 内置了<strong>版本检测</strong>：每次启动时向平台确认一次最新版本，比自己新就弹窗提示，用户点更新即可在 App 内完成下载与安装，不必再自己去下载中心找。</p><p>本页讲<strong>运营在后台需要做什么</strong>。打包与上传属于技术操作，由技术方完成。</p><h2 id="配置位置" tabindex="-1">配置位置 <a class="header-anchor" href="#配置位置" aria-label="Permalink to &quot;配置位置&quot;">​</a></h2><p>后台「基础配置 → App版本更新」。</p><div class="danger custom-block"><p class="custom-block-title">超级管理员专属</p><p>本配置只有超级管理员能修改。原因见下方「强制更新」一节。</p></div><h2 id="六个字段" tabindex="-1">六个字段 <a class="header-anchor" href="#六个字段" aria-label="Permalink to &quot;六个字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td><strong>更新检测总开关</strong></td><td>打开。关闭后 App 完全不检测新版本</td></tr><tr><td><strong>最新版本号(versionCode)</strong></td><td>技术方给出的整数版本号，每次发版都会比上一版大</td></tr><tr><td><strong>最新版本名</strong></td><td>展示给用户看的版本号，如 <code>1.0.4</code></td></tr><tr><td><strong>强制更新版本号</strong></td><td><strong>平时一律填 0</strong>（表示不强制）</td></tr><tr><td><strong>APK 下载地址</strong></td><td>技术方给出的完整下载链接，必须以 <code>https://</code> 开头</td></tr><tr><td><strong>更新说明</strong></td><td>用户会在弹窗里看到这段文字，一行一条</td></tr></tbody></table><h2 id="用户会看到什么" tabindex="-1">用户会看到什么 <a class="header-anchor" href="#用户会看到什么" aria-label="Permalink to &quot;用户会看到什么&quot;">​</a></h2><ul><li><strong>普通更新</strong>：弹窗显示版本号与更新说明，可以点「稍后再说」关掉。关掉后<strong>当天不再提示</strong>，第二天再提醒一次</li><li>点「立即更新」：App 内显示下载进度条，下载完成后唤起系统安装器</li><li>首次安装时，安卓系统会让用户授权「允许安装未知来源的应用」，这是系统流程，无法跳过</li></ul><h2 id="强制更新" tabindex="-1">强制更新 <a class="header-anchor" href="#强制更新" aria-label="Permalink to &quot;强制更新&quot;">​</a></h2><p>把「强制更新版本号」填成 M 之后，版本号小于 M 的用户会看到一个<strong>无法关闭</strong>的更新弹窗——不更新就用不了 App。</p><div class="danger custom-block"><p class="custom-block-title">这等同于对这批用户停服</p><p>只有在某个版本出现严重问题（如资金显示错误、无法下单）时才使用。填错的后果是把<strong>全部用户</strong>挡在门外。</p><p>系统已内置两道保护：</p><ol><li>保存时校验「强制更新版本号」不得大于「最新版本号」</li><li>填了大于 0 的值时会二次确认</li></ol><p>但这两道保护挡不住&quot;填了一个合法但过大的值&quot;。请确认清楚再保存。</p></div><h2 id="发版时的正确顺序" tabindex="-1">发版时的正确顺序 <a class="header-anchor" href="#发版时的正确顺序" aria-label="Permalink to &quot;发版时的正确顺序&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>技术方打包并上传安装包</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>技术方确认下载链接可访问</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>运营在后台填写配置并保存    ← 这一步之后用户才会收到提示</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>自行验证：用旧版本 App 打开，确认收到提示</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">顺序不要颠倒</p><p><strong>先确认下载链接可用，再改后台配置。</strong> 反过来的话，用户会收到更新提示但下载失败。</p></div><h2 id="与「下载地址配置」的区别" tabindex="-1">与「下载地址配置」的区别 <a class="header-anchor" href="#与「下载地址配置」的区别" aria-label="Permalink to &quot;与「下载地址配置」的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>下载地址配置</th><th>App版本更新</th></tr></thead><tbody><tr><td>面向谁</td><td><strong>还没装 App 的新用户</strong></td><td><strong>已经装了 App 的老用户</strong></td></tr><tr><td>在哪看到</td><td>用户端的下载中心页面</td><td>App 启动时的更新弹窗</td></tr></tbody></table><p>两者互不影响，但建议<strong>保持指向同一个版本</strong>，否则新用户装到的是旧包、装完立刻被提示更新。</p>`,20)])])}const u=a(p,[["render",r]]);export{g as __pageData,u as default};
